#include <stdio.h>

/* teste do desafio o-cadastro — counter_protocol (03-tdd 3.9.3).
   Cada cenario escreve num arquivo o cadastro que a pessoa "digitaria",
   aponta o stdin para esse arquivo (freopen), captura o stdout no proprio
   teste e le a linha de volta. Os nomes dos arquivos temporarios sao POR
   CENARIO. Nunca ha fclose de stdin/stdout — so fflush —, para o segundo
   freopen ficar legal (C11 7.21.4). Num cenario a mais alta e a segunda
   pessoa, no outro e a primeira: nenhuma linha fixa passa nos dois. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oCadastro(void);

SM_TEST(a_mais_alta_e_a_segunda) {
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "Ana 17 1.62\nBruno 18 1.75\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    oCadastro();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a ficha da mais alta", linha, "Bruno tem 18 anos e 1.75 m\n",
              "1.75 e maior que 1.62: a ficha impressa e a da segunda pessoa, inteira");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "o cadastro imprime uma linha so: nenhuma pergunta, nenhuma despedida");
    fclose(f);
}

SM_TEST(a_mais_alta_e_a_primeira) {
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "Carla 20 1.80\nDavi 19 1.70\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    oCadastro();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a ficha da mais alta", linha, "Carla tem 20 anos e 1.80 m\n",
              "quando a primeira pessoa e a mais alta, e a ficha dela que sai");
    fclose(f);
}

