#include <stdio.h>

typedef struct {
    char nome[40];
    int idade;
    double altura;
} Pessoa;

void oCadastro(void) {
    Pessoa a = {"", 0, 0.0};
    Pessoa b = {"", 0, 0.0};

    scanf("%39s", a.nome);
    scanf("%d", &a.idade);
    scanf("%lf", &a.altura);

    scanf("%39s", b.nome);
    scanf("%d", &b.idade);
    scanf("%lf", &b.altura);

    if (a.altura <= b.altura) {
        printf("%s tem %d anos e %.2f m\n", b.nome, b.idade, b.altura);
    } else {
        printf("%s tem %d anos e %.2f m\n", a.nome, a.idade, a.altura);
    }
}
